CREATE TABLE users (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), wallet_address VARCHAR(66) UNIQUE NOT NULL, email VARCHAR(255) UNIQUE, created_at TIMESTAMP DEFAULT NOW(), last_login TIMESTAMP DEFAULT NOW(), is_active BOOLEAN DEFAULT TRUE, metadata JSONB DEFAULT '{}'); CREATE TABLE wallets (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, chain_id VARCHAR(64) NOT NULL, address VARCHAR(255) NOT NULL, label VARCHAR(100), is_primary BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT NOW(), UNIQUE(user_id, chain_id, address)); CREATE TABLE tokens (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), symbol VARCHAR(20) NOT NULL, name VARCHAR(100) NOT NULL, decimals INTEGER NOT NULL DEFAULT 18, contract_address VARCHAR(66), chain_id VARCHAR(64) NOT NULL, is_native BOOLEAN DEFAULT FALSE, logo_url TEXT, created_at TIMESTAMP DEFAULT NOW(), UNIQUE(symbol, chain_id)); CREATE TABLE portfolio (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, token_id UUID REFERENCES tokens(id), amount DECIMAL(65, 18) NOT NULL DEFAULT 0, acquired_at TIMESTAMP DEFAULT NOW(), UNIQUE(user_id, token_id)); CREATE TABLE transactions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID REFERENCES users(id) ON DELETE SET NULL, wallet_id UUID REFERENCES wallets(id) ON DELETE SET NULL, token_id UUID REFERENCES tokens(id), hash VARCHAR(66) UNIQUE NOT NULL, from_address VARCHAR(255), to_address VARCHAR(255), amount DECIMAL(65, 18) NOT NULL, fee DECIMAL(65, 18) DEFAULT 0, status VARCHAR(50) DEFAULT 'pending', block_number BIGINT, timestamp TIMESTAMP DEFAULT NOW(), direction VARCHAR(20) CHECK (direction IN ('in', 'out', 'internal'))); CREATE TABLE nfts (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, token_id VARCHAR(66) NOT NULL, contract_address VARCHAR(66) NOT NULL, name VARCHAR(255), symbol VARCHAR(50), metadata JSONB DEFAULT '{}', chain_id VARCHAR(64) NOT NULL, acquired_at TIMESTAMP DEFAULT NOW(), UNIQUE(user_id, contract_address, token_id)); CREATE TABLE defi_positions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, protocol VARCHAR(100) NOT NULL, pool_address VARCHAR(66) NOT NULL, token_in_id UUID REFERENCES tokens(id), token_out_id UUID REFERENCES tokens(id), amount_in DECIMAL(65, 18), amount_out DECIMAL(65, 18), apy DECIMAL(10, 4), status VARCHAR(50) DEFAULT 'active', created_at TIMESTAMP DEFAULT NOW(), last_updated TIMESTAMP DEFAULT NOW()); CREATE INDEX idx_transactions_user_id ON transactions(user_id); CREATE INDEX idx_transactions_hash ON transactions(hash); CREATE INDEX idx_transactions_timestamp ON transactions(timestamp); CREATE INDEX idx_wallets_user_id ON wallets(user_id); CREATE INDEX idx_nfts_user_id ON nfts(user_id); CREATE INDEX idx_defi_positions_user_id ON defi_positions(user_id);